/// Static shell completion scripts for `lam`, generated by introspecting
/// the [ArgParser].
///
/// These scripts complete flag names, their fixed enum values
/// (`--to`, `--format`, `--flatten-cells`, `--completions`), and fall
/// back to file completion. They are *static*: no document is parsed and
/// `lam` is not invoked at completion time, so there is no per-keystroke
/// latency. Because the flag and value lists come straight from the
/// parser, they cannot drift from the real CLI.
///
/// Data-aware `.field` completion (offering keys from the actual file)
/// deliberately lives in the REPL — and, eventually, a language server —
/// where a persistent process parses the document once and reuses it.
library;

import 'package:args/args.dart';

/// Renders the completion script for [shell] ('bash', 'zsh', or 'fish').
String renderCompletions(String shell, ArgParser parser) => switch (shell) {
  'bash' => _bash(parser),
  'zsh' => _zsh(parser),
  'fish' => _fish(parser),
  _ => throw ArgumentError('Unsupported shell: $shell'),
};

/// All completable flag tokens: `--name`, `--no-name` (negatable flags),
/// and `-x` short forms.
List<String> _tokens(ArgParser p) {
  final tokens = <String>[];
  for (final o in p.options.values) {
    tokens.add('--${o.name}');
    if (o.isFlag && (o.negatable ?? false)) tokens.add('--no-${o.name}');
    if (o.abbr != null) tokens.add('-${o.abbr}');
  }
  return tokens;
}

String _bash(ArgParser p) {
  final cases = StringBuffer();
  for (final o in p.options.values) {
    final allowed = o.allowed;
    if (allowed == null || allowed.isEmpty) continue;
    final pat = StringBuffer('--${o.name}');
    if (o.abbr != null) pat.write('|-${o.abbr}');
    cases.writeln(
      '    $pat)\n'
      '      COMPREPLY=( \$(compgen -W "${allowed.join(' ')}" -- "\$cur") )\n'
      '      return ;;',
    );
  }
  final flags = _tokens(p).join(' ');
  return '''
# bash completion for lam. Source this file, or drop it in a
# bash-completion.d directory.
_lam() {
  local cur prev
  cur="\${COMP_WORDS[COMP_CWORD]}"
  prev="\${COMP_WORDS[COMP_CWORD-1]}"
  case "\$prev" in
${cases.toString().trimRight()}
  esac
  if [[ "\$cur" == -* ]]; then
    COMPREPLY=( \$(compgen -W "$flags" -- "\$cur") )
    return
  fi
  COMPREPLY=( \$(compgen -f -- "\$cur") )
}
complete -F _lam lam
''';
}

String _zsh(ArgParser p) {
  final specs = <String>[];
  for (final o in p.options.values) {
    final desc = _sanitizeZsh(o.help);
    final allowed = o.allowed;
    final String action;
    if (allowed != null && allowed.isNotEmpty) {
      action = ':${o.name}:(${allowed.join(' ')})';
    } else if (o.isFlag) {
      action = '';
    } else {
      action = ':${o.name}:_files';
    }
    if (o.abbr != null) {
      // Braces sit OUTSIDE the quotes so zsh brace-expands them into two
      // specs (`-p'[…]'` and `--pretty'[…]'`); quoting them makes
      // _arguments reject the literal `{…}` as an invalid argument.
      specs.add("{-${o.abbr},--${o.name}}'[$desc]$action'");
    } else {
      specs.add("'--${o.name}[$desc]$action'");
    }
  }
  specs.add("'*:file:_files'");
  // Autoload form: the file body *is* the completion function. Install
  // on \$fpath as `_lam` (Homebrew's zsh_completion.install does this);
  // there is no wrapper function or `compdef` call, per zsh convention.
  return '''
#compdef lam
# zsh completion for lam. Install on \$fpath as a file named _lam.
_arguments -s \\
    ${specs.join(' \\\n    ')}
''';
}

String _fish(ArgParser p) {
  final lines = <String>[
    '# fish completion for lam. Place in ~/.config/fish/completions/lam.fish.',
  ];
  for (final o in p.options.values) {
    final b = StringBuffer('complete -c lam');
    if (o.abbr != null) b.write(' -s ${o.abbr}');
    b.write(' -l ${o.name}');
    final allowed = o.allowed;
    if (allowed != null && allowed.isNotEmpty) {
      b.write(' -x -a "${allowed.join(' ')}"');
    }
    final desc = _sanitizeFish(o.help);
    if (desc.isNotEmpty) b.write(' -d "$desc"');
    lines.add(b.toString());
  }
  return '${lines.join('\n')}\n';
}

/// Strips characters that would break a single-quoted zsh `_arguments`
/// spec (`[`, `]`, `:`, `'`, backtick, backslash) and collapses
/// whitespace. Descriptions are hints, so lossy sanitisation is fine.
String _sanitizeZsh(String? help) {
  if (help == null) return '';
  return help
      .replaceAll(RegExp(r"[\[\]:'`\\]"), ' ')
      .replaceAll(RegExp(r'\s+'), ' ')
      .trim();
}

/// Strips characters that would break a double-quoted fish `-d` string
/// (`"`, backslash, backtick) and collapses whitespace.
String _sanitizeFish(String? help) {
  if (help == null) return '';
  return help
      .replaceAll(RegExp(r'[\\"`]'), ' ')
      .replaceAll(RegExp(r'\s+'), ' ')
      .trim();
}
